            # Compute KL divergence manually using custom CUDA kernel
            # This avoids the overhead of torch.nn.functional.kl_div and uses online softmax
            batch_size = 8192 * 2
            out = self.kll_div.elementwise_add_cuda(predictions, targets, reduction='batchmean')
        return out

