elementwise_kll_div_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_kll_div_kernel(const torch::Tensor a, const torch::Tensor b) {
    int size = a.numel();
    int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    // Compute log probabilities
    float log_probs = F.log(a);

    // Softmax over predictions
    torch::Tensor softmax_logs = F.softmax(log_probs, dim=-1);

    // Compute KL divergence manually using online softmax
    for (int i = 0; i < num_blocks * block_size; i += block_size) {
        int idx = i;
        float sum_exp = 0.0f;
        for (int j = 0; j < size; j++) {
            if (idx < j) {
                sum_exp += softmax_logs[j];
            }
        }

        // Normalize to get probabilities
        torch::Tensor probs = F.softmax(softmax_logs, dim=-1);

        // Compute KL divergence for each element
        float kll_div = 0.0f;
        for (int j = 0; j < size; j++) {
            if (j == idx) {
                kll_div += F.log(probs[j] - softmax_logs[j]);
            }
        }

        out[idx] = kll_div / sum_exp;
    }
}

